custom_css:
/* 花笺漫想
   by 狸狌主任
  禁止二传/商用等恶劣行为
  如有图案位移或字体颜色不清晰，按需修改即可，有些地方有注释*/


/* ═══ 字体链接 ═══ */
@import url("https://fontsapi.zeoseven.com/53/main/result.css");

/* ═══ 全局变量 ═══ */
:root {
    --parchment: #c8b896;
    --parchment-light: #d9ccb0;
    --parchment-dark: #a89070;
    --ink-deep: #3a2e1e;
    --ink-mid: #5c4e3a;
    --ink-pale: #8a7a62;
    --ink-faint: #b0a088;
    --whisper-line: rgba(90, 70, 40, 0.12);
}


/* ═══ 全局基础 ═══ */
* { scrollbar-width: none }
*::-webkit-scrollbar { display: none }

/* 选中文本颜色 */
::selection { background: rgba(168, 144, 112, 0.35) }

:is(textarea, #send_textarea) { resize: none }

/* ✩ 全局字体 ✩ */
body, body * {
    font-family: "ToneOZ-Tsuipita-TC", "Georgia", serif !important;
    font-weight: normal !important;
}

:is(.fa, .fas, .far, .fab, .fa-solid, .fa-regular, .fa-brands,
i[class*="fa-"], .mes_button, .mes_edit_buttons .menu_button,
.inline-drawer-icon, .drawer-icon),
[class*="fa-"]::before {
    font-family: "Font Awesome 6 Free", "Font Awesome 6 Brands", "FontAwesome" !important;
}

* { -webkit-tap-highlight-color: transparent !important; }

:is(.inline-drawer-header, .inline-drawer-toggle, .inline-drawer-icon,
.menu_button, #options_button, #extensionsMenuButton,
#send_but, #mes_stop):is(:active, :hover, :focus) {
    filter: none !important;
    opacity: 1 !important;
}


/* ═══ 背景图「修改url () 里的链接可更换背景」═══ */
/* ✩ 主背景 ✩ */
body {
    background: url('https://img.heliar.top/file/1772670824848_1772670798131.jpg') center / cover no-repeat fixed !important;
    background-attachment: fixed !important;
}

html body #bg1,
html body #bg2 {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
}

html body .shadow_shelf {
    background: transparent !important;
    box-shadow: none !important;
}

html body #holder { background: transparent !important; }
html body #chat_parent { background: transparent !important; }

html body #form_sheld {
    background: transparent !important;
    background-color: transparent !important;
}

html body #top-settings-holder {
    background: url('https://img.heliar.top/file/1774711156414_retouch_2026032823180904.png') top center / 100% auto no-repeat !important;
    background-color: transparent !important;
}

/* ✩ 侧边栏背景图  ✩ */
:is(#left-nav-panel, #right-nav-panel) {
    background: url('https://img.heliar.top/file/1772679175746_1772678778249.jpg') center / cover no-repeat fixed !important;
    height: 100dvh;
    max-height: 100dvh;
    padding-bottom: 0 !important;
}

.drawer-content {
    background: url('https://img.heliar.top/file/1772679175746_1772678778249.jpg') center / cover no-repeat fixed !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: unset !important;
}

.drawer-content.openDrawer {
    max-height: calc(100dvh - var(--topBarBlockSize)) !important;
    overflow-y: auto !important;
    padding-bottom: 10px !important;
}


/* ═══ 聊天区域 ═══ */
#chat {
    background: transparent !important;
    backdrop-filter: unset !important;
    -webkit-backdrop-filter: unset !important;
    box-shadow: unset !important;
    padding-block-start: 35px !important;
}

#chat::before { content: none !important }


/* ═══ 顶栏 ═══ */
#top-bar {
    box-shadow: unset !important;
    overflow: visible !important;
}

#top-bar::after { content: none !important }

#top-settings-holder {
    background: url('https://img.heliar.top/file/1774711156414_retouch_2026032823180904.png') top center / 100% auto no-repeat !important;
    background-color: transparent !important;
    border: 0 !important;
    border-block-end: none !important;
    backdrop-filter: none !important;
    padding: 0 8px 55px 8px !important;
    display: flex;
    flex-flow: row nowrap;
    justify-content: center;
    align-items: flex-start;
    min-height: 90px;
    gap: 1px;
    box-shadow: unset !important;
    overflow: visible !important;
}

#top-settings-holder > * {
    position: relative !important;
    z-index: 10 !important;
    pointer-events: auto !important;
    touch-action: manipulation !important;
}

.drawer-icon.fa-solid::before {
    content: '' !important;
    display: inline-block !important;
    inline-size: 28px !important;
    block-size: 28px !important;
    background: url('https://img.heliar.top/file/1772671971608_retouch_2026030508522684.png') center / contain no-repeat !important;
}

.drawer-icon {
    opacity: 0.8 !important;
    transition: opacity 0.25s !important;
    border: 0 !important;
    box-shadow: unset !important;
    background: transparent !important;
    min-width: 36px !important;
    min-height: 36px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

.drawer-icon:hover { opacity: 1 !important; }

.drawer-icon.openIcon.fa-solid::before,
.drawer-icon.open.fa-solid::before,
.drawer-icon:active.fa-solid::before {
    background-image: url('https://img.heliar.top/file/1774721834376_无标题5_20260329021658.png') !important;
}

#extensionTopBar {
    box-shadow: unset !important;
    border: 0 !important;
}


/* ═══ 收藏角色 ═══ */
#HotSwapWrapper {
    overflow-x: auto !important;
    overflow-y: visible !important;
    white-space: nowrap !important;
    -webkit-overflow-scrolling: touch !important;
    background: transparent !important;
    padding: 4px 8px !important;
    border-block-end: none !important;
    min-block-size: 45px !important;
}

#HotSwapWrapper .avatar {
    overflow: visible !important;
    display: inline-block !important;
    flex-shrink: 0 !important;
    opacity: 1 !important;
    visibility: visible !important;
}

#HotSwapWrapper .avatar img {
    opacity: 1 !important;
    visibility: visible !important;
}

.hotswap.avatars_inline {
    min-width: max-content !important;
    white-space: nowrap !important;
}


/* ═══ 头像框 ═══ */
.avatar {
    position: relative !important;
    border: 0 !important;
    overflow: visible !important;
}

.avatar img {
    border-radius: 0 !important;
    border: 0 !important;
    display: block !important;
    position: relative !important;
    z-index: 0 !important;
}

.avatar::after {
    content: '' !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    /* ▼ 框的大小比例 */
    width: 128% !important;
    height: 128% !important;
    background: url('https://img.heliar.top/file/1772673901531_1772644070314.webp') center / contain no-repeat !important;
    pointer-events: none !important;
    z-index: 1 !important;
}

/* ✩ 收藏角色头像框大小 ✩ */
#HotSwapWrapper .avatar::after {
    width: 130% !important;
    height: 135% !important;
}

/* ✩ 角色列表头像大小 ✩ */
#rm_print_characters_block .avatar,
.character_select .avatar {
    inline-size: 45px !important;
    block-size: 45px !important;
}

#rm_print_characters_block .avatar img,
.character_select .avatar img {
    inline-size: 45px !important;
    block-size: 45px !important;
    object-fit: cover !important;
}

#rm_print_characters_block .avatar::after,
.character_select .avatar::after {
    width: 130% !important;
    height: 138% !important;
}

/* ✩ 用户头像框 ✩ */
#user_avatar_block .avatar::after,
.persona_avatar .avatar::after,
#user-settings-block .avatar::after {
    width: 130% !important;
    height: 135% !important;
}

/* ✩ 角色编辑页头像框 ✩ */
#avatar_div .avatar::after,
.avatar_uploaded .avatar::after,
#form_create .avatar::after,
.ch_avatar .avatar::after {
    width: 125% !important;
    height: 120% !important;
}

/* ✩ 文件夹内小头像 ✩ */
#rm_print_characters_block .bogus_folder_avatars_block .avatar,
#rm_print_characters_block .bogus_folder_avatars_block .avatar img {
    inline-size: 30px !important;
    block-size: 30px !important;
}

#rm_print_characters_block .bogus_folder_avatars_block .avatar::after {
    width: 130% !important;
    height: 135% !important;
}

.group_select .avatar::after,
.character_select .group_member_avatar::after,
.avatar_collage .avatar::after,
[class*="group"] .avatar::after {
    display: none !important;
}


/* ═══ 消息布局 ═══ */
.mes {
    display: block !important;
    position: relative !important;
    overflow: visible !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: unset !important;
    /* ▼ 气泡之间的间距 */
    margin-block-end: 150px !important;
    padding: 0 !important;
    width: 100% !important;
    max-width: 100% !important;
    z-index: 0 !important;
}

/* 最后一条消息和输入框的间距 */
.last_mes {
    margin-block-end: 150px !important;
}

.mes.last_mes > *:has(:is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay)) {
    margin: 0 !important;
    padding: 0 !important;
}

.mes.last_mes { padding-block-start: 0 !important }
.mes.last_mes .mes_block { margin-block-start: 0 !important }


/* ═══ 聊天头像「修改 top/right/width 调整位置大小」 ═══ */
.mes .mesAvatarWrapper {
    display: block !important;
    position: absolute !important;
    /* ▼ 头像距气泡顶部的距离 */
    top: 70px !important;
    /* ▼ 头像水平偏移（负值=右移到外面） */
    right: -28% !important;
    z-index: 2 !important;
    /* ▼ 头像区域宽度 */
    width: 60% !important;
    padding: 0 !important;
    margin: 0 !important;
}

.mes .mesAvatarWrapper .avatar {
    width: 100% !important;
    height: auto !important;
    aspect-ratio: 1.3 / 1 !important;
    display: block !important;
    position: relative !important;
    overflow: visible !important;
    border: 0 !important;
}

.mes .mesAvatarWrapper .avatar img {
    position: absolute !important;
    /* ▼ 头像图片偏移 */
    top: -35% !important;
    left: -42% !important;
    /* ▼ 头像图片大小 */
    width: 90% !important;
    height: 80% !important;
    object-fit: cover !important;
    border-radius: 2px !important;
    border: 0 !important;
    display: block !important;
    z-index: 0 !important;
}

.mes .mesAvatarWrapper .avatar::after {
    content: '' !important;
    position: absolute !important;
    top: 3% !important;
    left: 3% !important;
    width: 106% !important;
    height: 200% !important;
    background: url('https://img.heliar.top/file/1772715449484_retouch_2026030520563856.png') center / contain no-repeat !important;
    pointer-events: none !important;
    z-index: 1 !important;
}


/* ═══ 气泡 ═══ */
.mes .mes_block {
    width: 100vw !important;
    max-width: 100vw !important;
    margin-left: calc(-50vw + 50%) !important;
    background: url('https://img.heliar.top/file/1772712322833_1772701059483.jpg') top center / 100% auto repeat-y !important;
    color: var(--ink-deep) !important;
    border-radius: 0 !important;
    border: none !important;
    box-shadow: none !important;
    overflow: visible !important;
    padding: 42vw 24px 150px 24px !important;
    min-block-size: 400px !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    box-sizing: border-box !important;
    position: relative !important;
    z-index: auto !important;
}

/* ✩ 贴纸 ✩ */
.mes .mes_block::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important;
    left: 0 !important;
    /* ▼ 贴纸装饰大小 */
    width: 200vw !important;
    height: 60vw !important;
    background: url('https://img.heliar.top/file/1772721418591_retouch_2026030522363057.png') top left / contain no-repeat !important;
    pointer-events: none !important;
    z-index: 1 !important;
}

/* ✩ 底部装饰 ✩ */
.mes .mes_block::after {
    content: '' !important;
    position: absolute !important;
    bottom: 0 !important;
    left: 0 !important;
    width: 100% !important;
    /* ▼ 底部装饰高度 */
    height: 200px !important;
    background: url('https://img.heliar.top/file/1772667503357_无标题4_20260305073417.png') bottom center / 100% auto no-repeat !important;
    pointer-events: none !important;
    z-index: 6 !important;
}

.mes .mes_block > * {
    position: relative !important;
    z-index: auto !important;
    min-width: 0 !important;
    max-width: 100% !important;
    box-sizing: border-box !important;
}

/* ✩ 花朵 ✩ */
.mes .ch_name::before {
    content: '' !important;
    position: absolute !important;
    /* ▼ 上下位置：改 -23vw 数值，更负=更高 */
    top: calc(-23vw + 40px) !important;
    left: -24px !important;
    width: 100vw !important;
    /* ▼ 装饰高度 */
    height: 25vw !important;
    /* ▼ 60% auto = 图片宽度占60%自动高度 */
    background: url('https://img.heliar.top/file/1774871855449_retouch_2026033019571484.png') top left / 60% auto no-repeat !important;
    pointer-events: none !important;
    z-index: 5 !important;
}

/* ✩ 鸟 ✩ */
.mes::before {
    content: '' !important;
    position: absolute !important;
    /* ▼ 鸟的上下位置：更负=更高 */
    top: -60vw !important;
    /* ▼ 鸟的左右位置：更负=更左 */
    left: -8vw !important;
    /* ▼ 鸟的大小 */
    width: 100vw !important;
    height: 100vw !important;
    background: url('https://img.heliar.top/file/1774883050882_retouch_2026033023034975.png') center / contain no-repeat !important;
    pointer-events: none !important;
    z-index: -1 !important;
}


/* ═══ 名字 / 信息栏 / 按钮 ═══ */
.mes .ch_name {
    display: block !important;
    position: static !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 !important;
    /* ▼ 名字距上方的间距 */
    margin-top: 40px !important;
    margin-bottom: 15px !important;
    pointer-events: auto !important;
    width: auto !important;
    box-sizing: border-box !important;
    overflow: visible !important;
    transform: none !important;
}

/* ✩ 角色名字 ✩ */
.mes .ch_name .name_text {
    display: inline !important;
    /* ▼ 名字大小 */
    font-size: 1.3em !important;
    font-weight: bold !important;
    color: var(--ink-deep) !important;
    letter-spacing: 1px !important;
    white-space: nowrap !important;
    vertical-align: baseline !important;
    position: relative !important;
    z-index: 50 !important;
}

/* ✩ 时间戳 ✩ */
.mes .ch_name .timestamp {
    font-size: 0.75em !important;
    color: #000000 !important;
    white-space: nowrap !important;
    margin: 0 !important;
    padding: 0 !important;
}

.mes .timestamp {
    order: 99 !important;
    align-self: flex-end !important;
    text-align: left !important;
    flex: 0 0 100% !important;
    display: block !important;
    margin-top: 10px !important;
}

/* ✩ 编辑按钮 ✩ */
.mes .ch_name .mes_buttons {
    display: flex !important;
    align-items: center !important;
    /* ▼ 铅笔和省略号之间的间距 */
    gap: 10px !important;
    margin-top: 8px !important;
    padding: 0 !important;
    z-index: 200 !important;
    visibility: visible !important;
    opacity: 1 !important;
    pointer-events: auto !important;
    position: relative !important;
    overflow: visible !important;
    transform: none !important;
    /* ▼ 按钮上移量 */
    top: -35px !important;
    left: 0 !important;
}

/* ✩ 铅笔图标 ✩ */
.mes .ch_name .mes_buttons .mes_edit {
    width: 28px !important;
    height: 28px !important;
    min-width: 28px !important;
    min-height: 28px !important;
    background: url('https://img.heliar.top/file/1772667504709_retouch_2026030507303485.png') center / contain no-repeat transparent !important;
    font-size: 0 !important;
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    pointer-events: auto !important;
    cursor: pointer !important;
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    border: 0 !important;
    box-shadow: unset !important;
    filter: unset !important;
}

.mes .ch_name .mes_buttons .mes_edit::before { content: none !important }
.mes .ch_name .mes_buttons .mes_edit > * { display: none !important }

/* ✩ 省略号图标 ✩ */
.mes .ch_name .mes_buttons .extraMesButtonsHint {
    width: 28px !important;
    height: 28px !important;
    min-width: 28px !important;
    min-height: 28px !important;
    background: url('https://img.heliar.top/file/1772667502720_retouch_2026030507225722.png') center / contain no-repeat transparent !important;
    font-size: 0 !important;
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    pointer-events: auto !important;
    cursor: pointer !important;
    color: transparent !important;
    -webkit-text-fill-color: transparent !important;
    border: 0 !important;
    box-shadow: unset !important;
    filter: unset !important;
}

.mes .ch_name .mes_buttons .extraMesButtonsHint > * { display: none !important }

/* ✩ 展开菜单 ✩ */
.mes .ch_name .mes_buttons .extraMesButtons {
    position: absolute !important;
    top: 100% !important;
    left: 0 !important;
    z-index: 300 !important;
    pointer-events: auto !important;
    flex-wrap: wrap !important;
    /* ▼ 展开菜单按钮间距 */
    gap: 8px !important;
    padding: 8px !important;
    background: transparent !important;
    border: none !important;
    min-width: 200px !important;
}

/* ✩ 展开菜单内按钮颜色 ✩ */
.mes .ch_name .mes_buttons .extraMesButtons .mes_button {
    pointer-events: auto !important;
    cursor: pointer !important;
    display: inline-flex !important;
    visibility: visible !important;
    opacity: 1 !important;
    color: #a08060 !important;
    -webkit-text-fill-color: #a08060 !important;
    background: transparent !important;
    border: 0 !important;
    box-shadow: none !important;
    font-size: 1em !important;
    filter: none !important;
    text-shadow: none !important;
}

.mes .ch_name .mes_buttons .extraMesButtons .mes_button :is(.fa, i, [class*="fa-"]) {
    color: #a08060 !important;
    -webkit-text-fill-color: #a08060 !important;
    font-size: 1.1em !important;
    opacity: 1 !important;
    filter: none !important;
    text-shadow: none !important;
    -webkit-text-stroke: 0 !important;
}

/* ✩ 其他按钮淡色 ✩ */
.mes .ch_name .mes_buttons > .mes_button:not(.mes_edit):not(.extraMesButtonsHint) {
    color: var(--ink-pale) !important;
    -webkit-text-fill-color: var(--ink-pale) !important;
    background-color: transparent !important;
    background-image: none !important;
    border: 0 !important;
    box-shadow: unset !important;
    filter: unset !important;
    opacity: 1 !important;
}


/* ═══ 编辑模式按钮 ═══ */
.mes .mes_edit_buttons {
    margin-block-start: 10px !important;
    position: relative !important;
    z-index: 200 !important;
    pointer-events: auto !important;
    /* ▼ 编辑按钮间距 */
    gap: 4px !important;
    justify-content: flex-start !important;
}

/* ✩ 编辑按钮颜色 ✩ */
.mes_edit_buttons,
.mes_edit_buttons *,
.mes_edit_buttons *::before {
    color: #a08060 !important;
    -webkit-text-fill-color: #a08060 !important;
    filter: none !important;
    text-shadow: none !important;
    box-shadow: none !important;
    -webkit-text-stroke: 0 !important;
    background: transparent !important;
    border: none !important;
    opacity: 1 !important;
}

.mes .mes_edit_buttons .mes_button,
.mes .mes_edit_buttons .menu_button {
    /* ▼ 每个编辑按钮的内边距 */
    padding: 4px 6px !important;
    margin: 0 !important;
    min-width: auto !important;
    font-size: 1em !important;
}


/* ═══ 正文样式「所有特殊文本的颜色和效果在这里修改」 ═══ */
.mes .mes_text {
    padding: 0 !important;
    text-align: justify !important;
    overflow-wrap: anywhere !important;
    /* ▼ 行高 */
    line-height: 2 !important;
    /* ▼ 正文颜色 */
    color: #3a2e1e !important;
    position: relative !important;
    z-index: 10 !important;
    font-size: 1em !important;
    /* ▼ 正文描边粗细和颜色 */
    -webkit-text-stroke: 0.2px #1a1a1a !important;
}

.mes .mes_text > p:first-of-type { margin-block-start: 0 !important }
.mes .mes_text > p:last-of-type { margin-block-end: 0 !important }

/* ✩ *心理* ✩ */
.mes .mes_text :is(em, i:not([class])) {
    font-style: italic !important;
    /* ▼ 心理文字颜色 */
    color: #8b2020 !important;
    -webkit-text-fill-color: #8b2020 !important;
    background: none !important;
    padding: 0 !important;
    border: none !important;
    display: inline !important;
    -webkit-box-decoration-break: clone !important;
    box-decoration-break: clone !important;
    /* ▼ 底线颜色 */
    border-bottom: 1.5px solid #6b1818 !important;
    -webkit-text-stroke: 0 !important;
}

/* ✩ **加粗** ✩ */
.mes .mes_text :is(strong, b) {
    /* ▼ 加粗颜色 */
    color: #1a1a1a !important;
