:is(#left-nav-panel, #right-nav-panel, .drawer-content, .popup, #user-settings-block) div:has(> input[type=checkbox]),
:is(#left-nav-panel, #right-nav-panel, .drawer-content, .popup, #user-settings-block) span:has(> input[type=checkbox]),
:is(#left-nav-panel, #right-nav-panel, .drawer-content, .popup, #user-settings-block) .toggle-setting {
    display: flex !important;
    align-items: center !important;
    flex-wrap: wrap !important;
}

#saved_regex_scripts > div > input[type=checkbox],
#saved_scoped_scripts > div > input[type=checkbox],
#saved_preset_scripts > div > input[type=checkbox],
div:has(> .regex_script_name) input[type=checkbox]:first-of-type {
    width: 0 !important;
    height: 0 !important;
    margin: 0 !important;
    padding: 0 !important;
    overflow: hidden !important;
    opacity: 0 !important;
    position: absolute !important;
}


/* ═══ 滑块 ═══ */
input[type=range] {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 100% !important;
    height: 3px !important;
    background: linear-gradient(90deg, rgba(168, 144, 112, 0.5), rgba(200, 184, 150, 0.3)) !important;
    border: 0 !important;
    border-radius: 2px !important;
    outline: none !important;
    margin: 20px 0 !important;
    overflow: visible !important;
}

input[type=range]::-webkit-slider-runnable-track {
    height: 3px !important;
    border: 0 !important;
    border-radius: 2px !important;
    background: linear-gradient(90deg, rgba(168, 144, 112, 0.5), rgba(200, 184, 150, 0.3)) !important;
}

input[type=range]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    width: 36px !important;
    height: 36px !important;
    background: url('https://img.heliar.top/file/1772670176740_retouch_2026030508223715.png') center / contain no-repeat !important;
    border: 0 !important;
    border-radius: 0 !important;
    margin-top: -17px !important;
}


/* ═══ 折叠/面板图标 ═══ */
.inline-drawer-icon {
    inline-size: 18px !important;
    block-size: 18px !important;
    background: url('https://img.heliar.top/file/1772671971608_retouch_2026030508522684.png') center / contain no-repeat !important;
    box-shadow: unset !important;
}

.inline-drawer-icon::before { content: none !important }

/* ✩ 面板图标颜色 ✩ */
:is(.drawer-content, .popup, #left-nav-panel, #right-nav-panel,
#WorldInfo, #saved_regex_scripts, #saved_scoped_scripts,
#completion_prompt_manager_list, .extension_container) :is(.fa, i.fa-solid, i.fa-regular, [class*="fa-"]):not(.menu_button) {
    color: var(--ink-pale) !important;
    opacity: 1 !important;
    filter: unset !important;
    text-shadow: unset !important;
    box-shadow: unset !important;
    -webkit-text-stroke: 0 !important;
}

#completion_prompt_manager_list :is(.fa-link, .fa-link-slash, [class*="fa-link"], [class*="fa-chain"]) {
    color: #c49070 !important;
}

#WorldInfo .inline-drawer-icon,
#world-info-editor .inline-drawer-icon,
.world_entry .inline-drawer-icon {
    inline-size: 35px !important;
    block-size: 35px !important;
}


/* ═══ 正则/角色管理/预设 ═══ */

/* ✩ 正则名称 ✩ */
.regex_script_name {
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    color: var(--ink-deep) !important;
}

/* ✩ 角色卡片 ✩ */
.avatar-container {
    border-radius: 0 !important;
    background: transparent !important;
    border: 2px solid transparent !important;
    box-shadow: unset !important;
    padding: 20px 8px 8px 8px !important;
}

.avatar-container.selected {
    border: 2px solid var(--parchment-dark) !important;
    box-shadow: 0 0 0 2px rgba(168, 144, 112, 0.3) !important;
}

.character_select {
    border: 1px solid transparent !important;
    border-radius: 0 !important;
    background: transparent !important;
}

.character_select:hover { border-color: var(--parchment-dark) !important }
#rm_print_characters_block { padding-block-end: 10px !important }

/* ✩ 预设条目 ✩ */
.completion_prompt_manager_prompt {
    background: rgba(240, 230, 210, 0.9) !important;
    border: 1px solid rgba(90, 70, 40, 0.12) !important;
    border-radius: 0 !important;
    color: var(--ink-deep) !important;
}

.completion_prompt_manager_prompt_disabled { opacity: 0.5 !important }

.completion_prompt_manager_prompt :is(.completion_prompt_manager_prompt_name, .prompt-manager-inspect-action, span) {
    color: var(--ink-deep) !important;
    visibility: visible !important;
    opacity: 1 !important;
}

.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name {
    color: var(--ink-pale) !important;
}

/* ✩ 提示词管理器头部 ✩ */
.completion_prompt_manager_header,
.completion_prompt_manager_header * {
    color: var(--ink-mid) !important;
    -webkit-text-fill-color: var(--ink-mid) !important;
    text-shadow: none !important;
    -webkit-text-stroke: 0 !important;
    filter: none !important;
    background: transparent !important;
    background-image: none !important;
    -webkit-background-clip: border-box !important;
    background-clip: border-box !important;
    box-shadow: none !important;
    border: none !important;
    opacity: 1 !important;
    visibility: visible !important;
}


/* ═══ 代码块/分割线 ═══ */
.mes_text pre {
    background: rgba(240, 230, 210, 0.8) !important;
    border: 1px solid rgba(90, 70, 40, 0.12) !important;
    border-radius: 0 !important;
    color: var(--ink-mid) !important;
}

.mes_text code {
    background: transparent !important;
    border: 0 !important;
    color: inherit !important;
}

hr {
    border: 0 !important;
    block-size: 1px !important;
    background: linear-gradient(90deg, transparent, rgba(90, 70, 40, 0.2), transparent) !important;
}


/* ═══ 弹窗 ═══ */
.popup,
#select_chat_popup,
.popper-modal {
    box-shadow: none !important;
    filter: none !important;
    -webkit-filter: none !important;
}

.popup .popup_content {
    background: rgba(240, 230, 210, 0.97) !important;
    border-radius: 0 !important;
    box-shadow: 2px 3px 15px rgba(60, 40, 20, 0.15) !important;
    filter: none !important;
    -webkit-filter: none !important;
    border: 1px solid rgba(90, 70, 40, 0.12) !important;
}

.popup,
.popup .popup_content,
.popup-body,
#shadow_popup,
#dialogue_popup,
#dialogue_popup .popup_content {
    background: rgba(230, 218, 195, 0.97) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
}

#toast-container > .toast { background-image: unset !important }

.toast {
    background: rgba(240, 230, 210, 0.97) !important;
    border-radius: 0 !important;
    color: var(--ink-deep) !important;
    box-shadow: 2px 3px 10px rgba(60, 40, 20, 0.12) !important;
}

.dropdown-menu,
.dropdown,
[class*="dropdown"],
.options-content,
.list-group {
    box-shadow: none !important;
    filter: none !important;
    -webkit-filter: none !important;
    border: 1px solid rgba(90, 70, 40, 0.12) !important;
    border-radius: 0 !important;
    background: rgba(240, 230, 210, 0.97) !important;
}

#select_chat_popup,
#select_chat_popup .popup_content,
#past-chats-popup,
.shadow_popup {
    background: rgba(235, 225, 200, 0.97) !important;
    backdrop-filter: blur(10px) !important;
    -webkit-backdrop-filter: blur(10px) !important;
    border: none !important;
    box-shadow: 2px 4px 20px rgba(60, 40, 20, 0.2) !important;
}

#select_chat_popup .select_chat_block_wrapper,
.select_chat_block,
.select_chat_block_wrapper > * {
    background: rgba(245, 235, 215, 0.9) !important;
    border: 1px solid rgba(90, 70, 40, 0.12) !important;
    margin-bottom: 4px !important;
    color: var(--ink-deep) !important;
}

#select_chat_popup .select_chat_block_wrapper *,
.select_chat_block * {
    color: var(--ink-deep) !important;
    -webkit-text-fill-color: var(--ink-deep) !important;
    visibility: visible !important;
    opacity: 1 !important;
}

#select_chat_popup input[type="search"],
#select_chat_popup input[type="text"],
#select_chat_popup .search_input {
    background: rgba(245, 235, 215, 0.95) !important;
    border: 1px solid rgba(90, 70, 40, 0.2) !important;
    color: var(--ink-deep) !important;
}


/* ═══ 加载动画 ═══ */
#preloader {
    position: fixed;
    inset: 0;
    z-index: 999999;
    background: #d9ccb0;
}

#load-spinner {
    position: absolute;
    inset: 0;
    margin: auto;
    inline-size: 80px;
    block-size: 80px;
    background: url('https://img.heliar.top/file/1774913764915_retouch_2026033107344198.png') center / contain no-repeat;
    animation: vintageFloat 2.5s ease-in-out infinite;
    transition: all var(--animation-duration-2x) ease-out;
}

#load-spinner::before { content: none !important }

@keyframes vintageFloat {
    0%, 100% { translate: 0 0; rotate: 0deg; opacity: 1 }
    50% { translate: 0 -10px; rotate: 15deg; opacity: 0.6 }
}


/* ═══ 信息栏 ═══ */
.mes :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    font-size: 0.95em !important;
    color: #5c4e3a !important;
    background: unset !important;
    padding-block: 4px !important;
    display: inline !important;
    visibility: visible !important;
    opacity: 1 !important;
    position: relative !important;
    transform: none !important;
    white-space: nowrap !important;
    padding-left: 4px !important;
    padding-right: 4px !important;
    margin: 0 !important;
    /* ▼ 信息栏偏移位置 */
    top: -50px !important;
    left: -60px !important;
}

.mes :is(.mes_timer, .mesIDDisplay, .tokenCounterDisplay):empty {
    display: none !important;
}


/* ═══ 删除楼层 ═══ */
.mes.selected {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
}

html body:not(#_):not(#_) .mes.selected .mes_block {
    box-shadow: inset 0 0 0 9999px rgba(60, 45, 25, 0.45) !important;
    -webkit-box-shadow: inset 0 0 0 9999px rgba(60, 45, 25, 0.45) !important;
}

html body:not(#_):not(#_):not(#_):not(#_) #dialogue_del_mes {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    padding: 8px 20px !important;
    position: absolute !important;
    bottom: 100% !important;
    left: 50% !important;
    transform: translateX(-50%) !important;
    z-index: 100 !important;
    width: auto !important;
    white-space: nowrap !important;
    gap: 20px !important;
    justify-content: center !important;
    align-items: center !important;
}

/* ✩ 删除键 ✩ */
html body:not(#_):not(#_):not(#_):not(#_) #dialogue_del_mes_ok {
    background: var(--ink-deep) !important;
    color: #f0e6d2 !important;
    -webkit-text-fill-color: #f0e6d2 !important;
    border: none !important;
    padding: 10px 24px !important;
    cursor: pointer !important;
    font-size: 1em !important;
    box-shadow: 0 2px 8px rgba(60, 40, 20, 0.3) !important;
}

/* ✩ 取消键 ✩ */
html body:not(#_):not(#_):not(#_):not(#_) #dialogue_del_mes_cancel {
    background: rgba(210, 195, 165, 0.95) !important;
    color: var(--ink-deep) !important;
    -webkit-text-fill-color: var(--ink-deep) !important;
    border: 1px solid rgba(90, 70, 40, 0.3) !important;
    padding: 10px 24px !important;
    cursor: pointer !important;
    font-size: 1em !important;
    box-shadow: 0 2px 8px rgba(60, 40, 20, 0.15) !important;
}


/* ═══ 菜单 ═══ */
html body:not(#_):not(#_):not(#_):not(#_) #options {
    border: none !important;
    outline: none !important;
    box-shadow: 2px 3px 12px rgba(60, 40, 20, 0.12) !important;
}

html body:not(#_):not(#_):not(#_):not(#_) #options > *,
html body:not(#_):not(#_):not(#_):not(#_) #options .list-group,
html body:not(#_):not(#_):not(#_):not(#_) #options .list-group-item,
html body:not(#_):not(#_):not(#_):not(#_) #options .options-content {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
}


/* ═══ 全局强制尖角/背景清除 ═══ */
html body:not(#_):not(#_) *,
html body:not(#_):not(#_) *::before,
html body:not(#_):not(#_) *::after {
    border-radius: 0 !important;
    -webkit-border-radius: 0 !important;
}

html body:not(#_):not(#_) #form_sheld {
    background: transparent !important;
    background-color: transparent !important;
}

html body:not(#_):not(#_) #send_form,
html body:not(#_):not(#_) #send_form:focus-within,
html body:not(#_):not(#_) body.no-blur #send_form {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
    -webkit-box-shadow: none !important;
}

html body:not(#_):not(#_) #qr--bar {
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
}


